using System.Text;
using System.Text.RegularExpressions;

namespace Aprillz.MewUI.MarkupAudit;

/// <summary>Rendered reference files keyed by file name, plus the extension methods left out as obsolete or non-fluent.</summary>
public sealed record MarkupReferenceOutput(
    IReadOnlyDictionary<string, string> Files,
    IReadOnlyList<string> Skipped,
    int MethodCount);

/// <summary>Renders the C# Markup reference (one Markdown file per receiver group) from an audit result.</summary>
public static class MarkupReferenceWriter
{
    /// <summary>First line of every generated file; the drift test and stale-file cleanup recognize generated files by it.</summary>
    public const string GENERATED_NOTICE =
        GENERATED_PREFIX + " --docs from the compiled assemblies. Do not edit; regenerate with: " +
        "dotnet run --project tools/MewUI.MarkupAudit/MewUI.MarkupAudit -- <assemblies> --docs docs/markup -->";

    private const string GENERATED_PREFIX = "<!-- Generated by MewUI.MarkupAudit";

    private const string CORE_ASSEMBLY = "Aprillz.MewUI";
    private const string EXTENSION_ASSEMBLY_PREFIX = "Aprillz.MewUI.";
    private const string MISC_GROUP = "Misc";
    private const string BIND_PREFIX = "Bind";
    private const string FILE_EXTENSION = ".md";
    private const string CONTROLS = "Aprillz.MewUI.Controls.";

    private static readonly Regex _namespaceQualifier = new(@"(?:[A-Za-z_][A-Za-z0-9_]*\.)+", RegexOptions.Compiled);
    private static readonly Regex _typeKeyword = new(
        @"\b(Boolean|String|Double|Single|Int32|Int64|Int16|UInt32|UInt64|UInt16|Byte|SByte|Char|Decimal|Object|Void)\b",
        RegexOptions.Compiled);

    private static readonly Dictionary<string, string> _keywords = new(StringComparer.Ordinal)
    {
        ["Boolean"] = "bool",
        ["String"] = "string",
        ["Double"] = "double",
        ["Single"] = "float",
        ["Int32"] = "int",
        ["Int64"] = "long",
        ["Int16"] = "short",
        ["UInt32"] = "uint",
        ["UInt64"] = "ulong",
        ["UInt16"] = "ushort",
        ["Byte"] = "byte",
        ["SByte"] = "sbyte",
        ["Char"] = "char",
        ["Decimal"] = "decimal",
        ["Object"] = "object",
        ["Void"] = "void",
    };

    // Invariant-culture spellings of the floating-point defaults that C# writes as named constants.
    private static readonly Dictionary<string, string> _specialDefaults = new(StringComparer.Ordinal)
    {
        ["Infinity"] = "double.PositiveInfinity",
        ["-Infinity"] = "double.NegativeInfinity",
        ["NaN"] = "double.NaN",
    };

    private sealed record GroupDefinition(string Name, string Title, string Description, IReadOnlyList<string> Types);

    // Order here is the order of the guide's Reference table; a receiver not listed walks its base chain to the nearest listed type.
    private static readonly GroupDefinition[] _groups =
    [
        new("Element", "Element, UIElement, FrameworkElement, Control",
            "Extensions every element or control accepts: layout, alignment, visibility, input events, attached-property helpers, and control appearance.",
            [CONTROLS + "Element", CONTROLS + "UIElement", CONTROLS + "FrameworkElement", CONTROLS + "Control", CONTROLS + "CommandSourceControl"]),
        new("Content", "Content and decorator controls",
            "Content controls, headers, tabs, scrolling, popups, and decorators.",
            [CONTROLS + "ContentControl", CONTROLS + "HeaderedContentControl", CONTROLS + "Decorator", CONTROLS + "Border", CONTROLS + "Expander",
             CONTROLS + "GroupBox", CONTROLS + "TabControl", CONTROLS + "TabItem", CONTROLS + "ShadowDecorator", CONTROLS + "RotationDecorator",
             CONTROLS + "TransformDecorator", CONTROLS + "Viewbox", CONTROLS + "TransitionContentControl", CONTROLS + "Popup",
             CONTROLS + "ScrollViewer", CONTROLS + "ScrollBar", CONTROLS + "Separator", CONTROLS + "PromptIcon"]),
        new("Window", "Window",
            "Window sizing modes, placement, lifecycle events, and window services.",
            ["Aprillz.MewUI.Window"]),
        new("Button", "Buttons and toggles",
            "Buttons, drop-down buttons, toggles, check boxes, radio buttons, and segmented controls.",
            [CONTROLS + "Button", CONTROLS + "DropDownBase", CONTROLS + "DropDownButton", CONTROLS + "SplitButton", CONTROLS + "ButtonGroup",
             CONTROLS + "SegmentedBase", CONTROLS + "SegmentedControl", CONTROLS + "SegmentButton", CONTROLS + "ToggleBase",
             CONTROLS + "ToggleButton", CONTROLS + "CheckBox", CONTROLS + "RadioButton", CONTROLS + "ToggleSwitch"]),
        new("TextBox", "Text input",
            "Single-line, multi-line, and password text boxes.",
            [CONTROLS + "TextBase", CONTROLS + "TextBox", CONTROLS + "MultiLineTextBox", CONTROLS + "PasswordBox"]),
        new("Input", "Value input",
            "Range controls, numeric input, progress indicators, calendar, date, and color pickers.",
            [CONTROLS + "RangeBase", CONTROLS + "Slider", CONTROLS + "ProgressBar", CONTROLS + "ProgressRing", CONTROLS + "ProgressIndicator",
             CONTROLS + "NumericUpDown", CONTROLS + "Calendar", CONTROLS + "DatePicker", CONTROLS + "ColorPicker"]),
        new("ListBox", "Items controls",
            "ItemsControl, ListBox, ComboBox, and navigation lists.",
            [CONTROLS + "ItemsControl", CONTROLS + "ScrollableItemsBase", CONTROLS + "ListBox", CONTROLS + "ComboBox",
             CONTROLS + "NavigationList", CONTROLS + "NavigationView"]),
        new("GridView", "GridView",
            "GridView and its columns.",
            [CONTROLS + "GridView", CONTROLS + "GridViewColumn"]),
        new("TreeView", "TreeView",
            "TreeView nodes, expansion, and selection.",
            [CONTROLS + "TreeView"]),
        new("Menu", "Menus",
            "Menu, MenuBar, MenuItem, and ContextMenu.",
            [CONTROLS + "Menu", CONTROLS + "MenuBar", CONTROLS + "MenuItem", CONTROLS + "ContextMenu"]),
        new("ToolBar", "ToolBar",
            "ToolBar bands, groups, and items.",
            [CONTROLS + "ToolBar", CONTROLS + "ToolBarBand", CONTROLS + "ToolBarGroup", CONTROLS + "ToolBarEntry", CONTROLS + "ToolBarItem",
             CONTROLS + "ToolBarLabelItem", CONTROLS + "ToolBarMenuItem", CONTROLS + "ToolBarSplitItem", CONTROLS + "ToolBarToggleItem"]),
        new("Panel", "Panels",
            "StackPanel, Grid, DockPanel, WrapPanel, UniformGrid, SplitPanel, and Canvas.",
            [CONTROLS + "Panel", CONTROLS + "StackPanel", CONTROLS + "Grid", CONTROLS + "DockPanel", CONTROLS + "SplitPanel",
             CONTROLS + "UniformGrid", CONTROLS + "WrapPanel", CONTROLS + "Canvas"]),
        new("Shape", "Shapes and glyphs",
            "Shape, Line, Rectangle, PathShape, and GlyphElement.",
            ["Aprillz.MewUI.Shape", "Aprillz.MewUI.Line", "Aprillz.MewUI.Rectangle", "Aprillz.MewUI.PathShape", CONTROLS + "GlyphElement"]),
        new("Image", "Image",
            "Image source, stretch, alignment, and view box.",
            [CONTROLS + "Image"]),
        new("Text", "Text",
            "TextBlock, Run, MarkupTextBlock, and Label.",
            [CONTROLS + "TextBlock", CONTROLS + "Run", CONTROLS + "MarkupTextBlock", CONTROLS + "Label"]),
        new("Binding", "Binding",
            "Generic Bind overloads and binding path builders.",
            ["Aprillz.MewUI.BindingPath"]),
        new(MISC_GROUP, "Miscellaneous",
            "Timer, style sheet, command, application builder, design-time size, Ref, and Apply.",
            ["Aprillz.MewUI.DispatcherTimer", "Aprillz.MewUI.StyleSheet", "Aprillz.MewUI.Command", "Aprillz.MewUI.ApplicationBuilder"]),
    ];

    // Declaring classes whose receiver constraint would otherwise place them under a control group, or whose return type is not the receiver.
    private static readonly Dictionary<string, string> _declaringTypeGroups = new(StringComparer.Ordinal)
    {
        [CONTROLS + "BindingExtensions"] = "Binding",
        ["Aprillz.MewUI.IndexedBindingPathExtensions"] = "Binding",
        ["Aprillz.MewUI.InpcBindingPathExtensions"] = "Binding",
        ["Aprillz.MewUI.MewPropertyBindingPathExtensions"] = "Binding",
        [CONTROLS + "DesignExtensions"] = MISC_GROUP,
        ["Aprillz.MewUI.FluentExtensions"] = MISC_GROUP,
        ["Aprillz.MewUI.WindowExtensions"] = "Window",
    };

    // Tree queries that happen to return an Element; they are not markup.
    private static readonly HashSet<string> _excludedDeclaringTypes = new(StringComparer.Ordinal)
    {
        "Aprillz.MewUI.VisualTree",
        "Aprillz.MewUI.LogicalTree",
    };

    private static readonly Dictionary<string, string> _typeGroups = _groups
        .SelectMany(static group => group.Types.Select(type => (type, group.Name)))
        .ToDictionary(static pair => pair.type, static pair => pair.Name, StringComparer.Ordinal);

    /// <summary>Renders every group file without touching the file system.</summary>
    public static MarkupReferenceOutput Render(AuditResult result)
    {
        var files = new SortedDictionary<string, string>(StringComparer.Ordinal);
        var skipped = new List<string>();
        var byFile = new Dictionary<string, List<ExtensionMethodRecord>>(StringComparer.Ordinal);
        var methodCount = 0;

        foreach (var record in result.Inventory)
        {
            if (!IsFluent(record))
            {
                skipped.Add($"{record.DeclaringType}.{record.Name}");
                continue;
            }

            var file = FileOf(record);
            if (!byFile.TryGetValue(file, out var records))
            {
                records = new List<ExtensionMethodRecord>();
                byFile[file] = records;
            }

            records.Add(record);
            methodCount++;
        }

        foreach (var (file, records) in byFile)
        {
            files[file] = RenderFile(file, records);
        }

        return new MarkupReferenceOutput(files, skipped, methodCount);
    }

    /// <summary>Writes the group files into the directory and deletes generated files that no longer have a group.</summary>
    public static MarkupReferenceOutput Write(AuditResult result, string outputDirectory)
    {
        var output = Render(result);
        Directory.CreateDirectory(outputDirectory);
        var encoding = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false);

        foreach (var (file, content) in output.Files)
        {
            File.WriteAllText(Path.Combine(outputDirectory, file), content, encoding);
        }

        foreach (var path in Directory.EnumerateFiles(outputDirectory, "*" + FILE_EXTENSION))
        {
            if (!output.Files.ContainsKey(Path.GetFileName(path)) && IsGeneratedFile(path))
            {
                File.Delete(path);
            }
        }

        return output;
    }

    /// <summary>True when the file starts with the generated-file notice.</summary>
    public static bool IsGeneratedFile(string path)
    {
        using var reader = new StreamReader(path);
        return reader.ReadLine()?.StartsWith(GENERATED_PREFIX, StringComparison.Ordinal) == true;
    }

    /// <summary>File name of the reference page an extension package's methods are written to.</summary>
    public static string ExtensionFileName(string assemblyName)
    {
        var name = assemblyName.StartsWith(EXTENSION_ASSEMBLY_PREFIX, StringComparison.Ordinal)
            ? assemblyName[EXTENSION_ASSEMBLY_PREFIX.Length..]
            : assemblyName;
        return name + FILE_EXTENSION;
    }

    private static bool IsFluent(ExtensionMethodRecord record)
    {
        if (record.Obsolete != null || _excludedDeclaringTypes.Contains(record.DeclaringType))
        {
            return false;
        }

        if (_declaringTypeGroups.ContainsKey(record.DeclaringType) || record.Name.StartsWith(BIND_PREFIX, StringComparison.Ordinal))
        {
            return true;
        }

        return record.ReturnType == ShortName(record.Receiver.Type);
    }

    private static string FileOf(ExtensionMethodRecord record)
    {
        if (record.Assembly != CORE_ASSEMBLY)
        {
            return ExtensionFileName(record.Assembly);
        }

        if (_declaringTypeGroups.TryGetValue(record.DeclaringType, out var declared))
        {
            return declared + FILE_EXTENSION;
        }

        var receiver = record.Receiver;
        if (receiver.ConstraintType != null)
        {
            foreach (var type in new[] { receiver.ConstraintType }.Concat(receiver.BaseTypes))
            {
                if (_typeGroups.TryGetValue(StripGenericArguments(type), out var group))
                {
                    return group + FILE_EXTENSION;
                }
            }
        }

        return MISC_GROUP + FILE_EXTENSION;
    }

    private static string RenderFile(string file, List<ExtensionMethodRecord> records)
    {
        var builder = new StringBuilder();
        builder.Append(GENERATED_NOTICE).Append('\n');

        var groupName = file[..^FILE_EXTENSION.Length];
        var group = _groups.FirstOrDefault(candidate => candidate.Name == groupName);
        if (group == null)
        {
            var assembly = records[0].Assembly;
            builder.Append("# ").Append(groupName).Append(" markup reference\n\n");
            builder.Append("Fluent extensions declared by the `").Append(assembly).Append("` package.\n");
        }
        else
        {
            builder.Append("# ").Append(group.Title).Append(" markup reference\n\n");
            builder.Append(group.Description).Append('\n');
        }

        var sections = records
            .GroupBy(static record => record.Receiver.ConstraintType ?? string.Empty, StringComparer.Ordinal)
            .OrderBy(static section => section.First().Receiver.BaseTypes.Count)
            .ThenBy(static section => section.Key, StringComparer.Ordinal);

        foreach (var section in sections)
        {
            RenderSection(builder, section.Key, section.ToList());
        }

        return builder.ToString();
    }

    private static void RenderSection(StringBuilder builder, string constraintType, List<ExtensionMethodRecord> records)
    {
        var anyGeneric = records.Any(static record => record.Receiver.IsGenericParameter);
        string title;
        string receiverLine;
        if (constraintType.Length == 0)
        {
            var referenceOnly = records.All(static record => record.Receiver.Constraints.Contains("class", StringComparer.Ordinal));
            title = referenceOnly ? "Any reference type" : "Any type";
            receiverLine = referenceOnly ? "Receiver: any reference type (`where T : class`)." : "Receiver: any type.";
        }
        else
        {
            var shortName = ShortName(constraintType);
            title = Escape(shortName);
            receiverLine = anyGeneric
                ? $"Receiver: `{shortName}` and derived types (`where T : {shortName}`)."
                : $"Receiver: `{shortName}`.";
        }

        builder.Append("\n### ").Append(title).Append("\n\n");
        builder.Append(receiverLine).Append("\n\n");
        builder.Append("| Method | Sets | Summary |\n|---|---|---|\n");

        var rows = records
            .Select(record => (record, Method: FormatMethod(record)))
            .OrderBy(static row => row.record.Name, StringComparer.Ordinal)
            .ThenBy(static row => row.Method, StringComparer.Ordinal);

        foreach (var (record, method) in rows)
        {
            builder.Append("| `").Append(EscapePipe(method)).Append("` | ")
                .Append(FormatSets(record)).Append(" | ")
                .Append(Escape(record.Summary ?? string.Empty)).Append(" |\n");
        }
    }

    private static string FormatMethod(ExtensionMethodRecord record)
    {
        var builder = new StringBuilder(record.Name).Append('(');
        for (var index = 0; index < record.Parameters.Count; index++)
        {
            var parameter = record.Parameters[index];
            if (index > 0)
            {
                builder.Append(", ");
            }

            if (parameter.IsParams)
            {
                builder.Append("params ");
            }

            if (parameter.Modifier != null)
            {
                builder.Append(parameter.Modifier).Append(' ');
            }

            builder.Append(KeywordTypes(parameter.Type.TrimEnd('&'))).Append(' ').Append(parameter.Name);
            if (parameter.DefaultValue != null)
            {
                builder.Append(" = ").Append(DefaultText(parameter.DefaultValue));
            }
        }

        return builder.Append(')').ToString();
    }

    private static string FormatSets(ExtensionMethodRecord record)
    {
        switch (record.Kind)
        {
            case ExtensionKinds.EVENT:
                return Code(record.TargetMembers.Select(static member => "event " + member));
            case ExtensionKinds.BIND:
                var bound = record.TargetMembers.Count > 0 ? record.TargetMembers : [record.Name[BIND_PREFIX.Length..]];
                return Code(bound.Select(static member => "bind " + member));
            case ExtensionKinds.OTHER:
                return string.Empty;
        }

        var hinted = record.Parameters
            .Where(static parameter => parameter.SetsMember != null)
            .Select(static parameter => parameter.SetsMember!)
            .Distinct(StringComparer.Ordinal)
            .Concat(record.Constants.Select(static constant => $"{constant.Member} = {ConstantText(constant)}"))
            .ToArray();

        return Code(hinted.Length > 0 ? hinted : record.TargetMembers);
    }

    private static string ConstantText(ConstantHintRecord constant)
    {
        var value = constant.Value ?? "null";
        if (value is "True" or "False")
        {
            return value.ToLowerInvariant();
        }

        var isEnum = constant.ValueType != null && !constant.ValueType.StartsWith("System.", StringComparison.Ordinal);
        return isEnum ? MemberOnly(value) : value;
    }

    private static string DefaultText(string value)
    {
        return _specialDefaults.TryGetValue(value, out var special) ? special : MemberOnly(value);
    }

    private static string Code(IEnumerable<string> items)
    {
        return string.Join(", ", items.Select(static item => $"`{EscapePipe(item)}`"));
    }

    private static string MemberOnly(string qualified)
    {
        if (qualified.Length == 0 || qualified[0] == '"' || qualified[0] == '-' || char.IsDigit(qualified[0]))
        {
            return qualified;
        }

        var dot = qualified.LastIndexOf('.');
        return dot >= 0 ? qualified[(dot + 1)..] : qualified;
    }

    private static string KeywordTypes(string type) => _typeKeyword.Replace(type, static match => _keywords[match.Value]);

    private static string ShortName(string fullType) => _namespaceQualifier.Replace(fullType, string.Empty);

    private static string StripGenericArguments(string type)
    {
        var angle = type.IndexOf('<');
        return angle >= 0 ? type[..angle] : type;
    }

    private static string EscapePipe(string text) => text.Replace("|", "\\|");

    private static string Escape(string text) => EscapePipe(text).Replace("<", "&lt;").Replace(">", "&gt;");
}
